={
  "messaging_product": "whatsapp",
  "to": "{{ $('Define Variables').item.json.phone_num }}",
  "type": "interactive",
  "interactive": {
    "type": "list",
    "header": {
      "type": "text",
      "text": "Konfirmasi Laporan"
    },
    "body": {
      "text": "*Laporan Kuota Anda*\n━━━━━━━━━━━━━━━━━━━━\nTerpakai: {{$node['POST to Quota Backend'].json.used}} GB\nTersisa: {{$node['POST to Quota Backend'].json.remaining}} GB\n━━━━━━━━━━━━━━━━━━━━\n\nSilahkan Konfirmasi Laporan Penggunaan Kuota"
    },
    "action": {
      "button": "Konfirmasi",
      "sections": [
        {
          "title": "Layanan",
          "rows": [
            {
              "id": "quota_Confirmed",
              "title": "Laporan Terkonfirmasi"
            },
            {
              "id": "quota_notConfirmed",
              "title": "Laporan Kuota Salah"
            }
          ]
        }
      ]
    }
  }
}

={
